// SINGLE SOURCE OF TRUTH: every string below must match section 9 of the WF-C2 system
// prompt word-for-word in substance. BUG-R35 — this tool used to carry its own numbers
// (£11k ceiling, "all England and Wales", 5–10yr inverter, 0% finance rates) which
// contradicted the prompt. The prompt answers almost everything; this tool is the rare
// fallback. If the two ever disagree again, the customer gets a coin flip.
try {
  var input = $input.first().json;
  var toolInput = input.toolInput || {};
  var toolUseId = input.toolUseId || '';
  var topic = (toolInput.topic || toolInput.category || toolInput.subject || '').toLowerCase().trim();

  var info = {
    hours: 'The Solarify office is open Monday to Friday 8am to 6pm and Saturday 9am to 1pm, closed Sunday and bank holidays. Survey visits themselves run Monday to Friday only, never Saturday or Sunday, and need at least 48 hours notice. This WhatsApp line answers any time.',
    services: 'Solarify installs residential solar PV, typically £5,000 to £9,500 all in, with a free survey first. Battery storage as an add-on is typically £3,000 to £6,500, with inverter compatibility checked at the survey. Monitoring and maintenance: annual plan £149, panel clean £95, fault callout £85 plus parts. Commercial work is handled by a separate specialist team. We do not install heat pumps, insulation, boilers or EV chargers.',
    pricing: 'Residential solar PV is typically £5,000 to £9,500 all in. Battery storage as an add-on is typically £3,000 to £6,500. Only the free survey produces a fixed quote for their actual roof.',
    subsidies: '0% VAT on home solar and batteries, currently in place until March 2027 — say currently, never imply it is permanent. The Smart Export Guarantee pays for electricity exported to the grid. Typical payback is 7 to 10 years at current energy prices. Grants exist but are aimed at lower-income households and people on certain benefits rather than everyone; never promise a specific grant or that funding will be approved.',
    finance: 'We do have finance options, and the team walks through the terms at the survey. Do not quote rates or monthly figures.',
    warranty: '10-year workmanship guarantee, 25-year panel performance warranty and 10-year inverter warranty. All work is MCS certified and HIES registered with an insurance-backed guarantee.',
    serviceArea: 'Greater Manchester, Leeds, Sheffield, Liverpool and surrounding areas within roughly 40 miles. Confirm the postcode when booking. Outside that area it is waiting list only.',
    process: 'The survey is free, no obligation, and takes 45 to 60 minutes. The team prepares a full written quote after the visit. Installation is one day for most homes, two for complex systems.',
    contact: 'The best way is to book a free survey right here in the chat. They can also ask their question here and the team will follow it up, or call the office during working hours.',
    about: 'Solarify Ltd, UK solar installation specialists. Established 2017, over 1,400 installations, 4.8 Google rating from 300+ reviews. MCS certified, HIES registered, insurance-backed guarantee on all work. Solar PV and battery storage only.'
  };

  var result = info[topic];
  // An empty topic must NOT fall into the substring loop: ''.indexOf('') === 0,
  // so key.indexOf(topic) matches the first key and silently returns opening hours.
  if (!result && topic) {
    var keys = Object.keys(info);
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i].toLowerCase();
      if (topic.indexOf(k) >= 0 || k.indexOf(topic) >= 0) {
        result = info[keys[i]];
        break;
      }
    }
  }
  if (!result) {
    result = 'I can answer questions about our services, pricing, government incentives, finance, warranties, service area, installation process, opening hours, or how to contact us. Which would you like to know about?';
  }

  return [{ json: { toolCallId: toolUseId, result: result } }];
} catch (e) {
  var fallbackId = '';
  try { fallbackId = $input.first().json.toolUseId; } catch(x) {}
  return [{ json: { toolCallId: fallbackId || 'unknown', result: 'I have information about our services, pricing, incentives and installation process. What would you like to know?' } }];
}

